using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json;

namespace Swapping.GameLogic.Online;

/// <summary>What the server answered: the value, or the HTTP status and the error code (status 0 = no answer).</summary>
public sealed record ApiAnswer<T>(T? Value, int Status, string? Code)
{
    public bool Ok => Status is >= 200 and < 300;
}

/// <summary>A new account: the access code generated by the server is shown once; the token keeps the session.</summary>
public sealed record NewAccount(string Name, string AccessCode, string Token);

public sealed record Session(string Name, string Token);

public sealed record RankLine(int Rank, string Name, int TimeMs, int Swaps);

/// <summary>My place in a level's ranking; <see cref="Place"/> is null with no result there yet.</summary>
public sealed record MyPlace(int? Place, int TotalPlayers)
{
    public int Rank => Place ?? 0;
}

/// <summary>
/// The game's client of the API (user, 2026-11-05): create an account (the server generates the access code),
/// log in, send a finished level, read a level's ranking and my place in it. No offline queue: when the
/// server does not answer, the answer has status 0 and code "Offline", and the game just says so.
/// </summary>
public sealed class GameApi(HttpClient http)
{
    private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);

    public async Task<ApiAnswer<NewAccount>> CreateAccountAsync(string name)
    {
        var icons = await SendAsync<List<string>>(HttpMethod.Get, "/icons", null, null);
        if (!icons.Ok || icons.Value is not { Count: > 0 } list)
            return new(null, icons.Status, icons.Code);
        var created = await SendAsync<CreatedBody>(HttpMethod.Post, "/profiles", null, new { name, icon = list[0] });
        return created.Value is { } body
            ? new(new NewAccount(body.Name, body.AccessCode, body.Token), created.Status, null)
            : new(null, created.Status, created.Code);
    }

    public async Task<ApiAnswer<Session>> LoginAsync(string name, string accessCode)
    {
        var login = await SendAsync<LoginBody>(HttpMethod.Post, "/sessions", null, new { name, accessCode });
        return login.Value is { } body ? new(new Session(body.Name, body.Token), login.Status, null) : new(null, login.Status, login.Code);
    }

    public async Task<ApiAnswer<bool>> SubmitAsync(string token, RunResult result)
    {
        var sent = await SendAsync<JsonElement>(HttpMethod.Post, "/results", token, new
        {
            levelId = result.LevelId,
            timeMs = result.TimeMs,
            swaps = result.Swaps,
            deaths = result.Deaths,
            roomRestarts = result.RoomRestarts,
            finishedAt = result.FinishedAt,
        });
        return new(sent.Ok, sent.Status, sent.Code);
    }

    public async Task<ApiAnswer<IReadOnlyList<RankLine>>> RankingAsync(string levelId, int top = 10)
    {
        var view = await SendAsync<RankingBody>(HttpMethod.Get, $"/rankings/{Uri.EscapeDataString(levelId)}?mode=time&top={top}", null, null);
        return view.Value is { } body
            ? new(body.Entries.Select(e => new RankLine(e.Rank, e.Name, e.TimeMs, e.Swaps)).ToList(), view.Status, null)
            : new(null, view.Status, view.Code);
    }

    public async Task<ApiAnswer<MyPlace>> MyRankAsync(string token, string levelId)
    {
        var mine = await SendAsync<MyRankBody>(HttpMethod.Get, $"/rankings/{Uri.EscapeDataString(levelId)}/me?mode=time", token, null);
        if (mine.Status == 404 && mine.Code == "NoResult")
            return new(new MyPlace(null, 0), 200, null);
        return mine.Value is { } body ? new(new MyPlace(body.Rank, body.TotalPlayers), mine.Status, null) : new(null, mine.Status, mine.Code);
    }

    private async Task<ApiAnswer<T>> SendAsync<T>(HttpMethod method, string path, string? token, object? body)
    {
        try
        {
            using var request = new HttpRequestMessage(method, path);
            if (token is not null)
                request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token);
            if (body is not null)
                request.Content = JsonContent.Create(body, options: Json);
            using var response = await http.SendAsync(request);
            var status = (int)response.StatusCode;
            if (response.IsSuccessStatusCode)
                return new(await response.Content.ReadFromJsonAsync<T>(Json), status, null);
            string? code = null;
            try
            {
                var problem = await response.Content.ReadFromJsonAsync<JsonElement>(Json);
                if (problem.ValueKind == JsonValueKind.Object && problem.TryGetProperty("code", out var c))
                    code = c.GetString();
            }
            catch (JsonException)
            {
            }
            return new(default, status, code ?? (status == 429 ? "TooManyRequests" : null));
        }
        catch (Exception e) when (e is HttpRequestException or TaskCanceledException or JsonException)
        {
            return new(default, 0, "Offline");
        }
    }

    private sealed record CreatedBody(string Name, string AccessCode, string Token);
    private sealed record LoginBody(string Name, string Token);
    private sealed record RankingBody(List<RankingEntryBody> Entries);
    private sealed record RankingEntryBody(int Rank, string Name, int TimeMs, int Swaps);
    private sealed record MyRankBody(int Rank, int TimeMs, int Swaps, int TotalPlayers);
}

/// <summary>Short Portuguese messages for the menu.</summary>
public static class OnlineText
{
    public static string Error(int status, string? code) => (status, code) switch
    {
        (0, _) => "servidor fora do ar",
        (401, "InvalidToken") => "sessão expirada: entre de novo",
        (401, _) => "nome ou código errado",
        (423, _) or (429, _) => "muitas tentativas: espere um pouco",
        (409, "NameTaken") => "esse nome já existe",
        (400, "InvalidName") => "nome inválido: 3 a 16 letras, números, _ ou -",
        (409, "LevelLocked") => "termine o nível anterior nesta conta",
        (422, _) => "resultado recusado pelo servidor",
        _ => $"erro no servidor ({status})",
    };
}
